package com.agacostays.payment.service.impl;
import com.agacostays.payment.config.PaymentGatewayProperties; import com.agacostays.payment.entity.*; import com.agacostays.payment.dto.request.PaymentWebhookRequest; import com.agacostays.payment.enums.*; import com.agacostays.payment.exception.*; import com.agacostays.payment.producer.PaymentEventProducer; import com.agacostays.payment.repository.*; import com.agacostays.payment.service.*; import java.nio.charset.StandardCharsets; import java.time.Instant; import java.util.UUID; import javax.crypto.Mac; import javax.crypto.spec.SecretKeySpec; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @Transactional public class PaymentWebhookServiceImpl implements PaymentWebhookService { private final PaymentGatewayProperties props; private final PaymentWebhookLogRepository logs; private final PaymentRepository payments; private final PaymentTransactionRepository transactions; private final PaymentEventProducer events; public PaymentWebhookServiceImpl(PaymentGatewayProperties p,PaymentWebhookLogRepository l,PaymentRepository pr,PaymentTransactionRepository t,PaymentEventProducer e){props=p;logs=l;payments=pr;transactions=t;events=e;} public void process(PaymentWebhookRequest r,String raw,String header){String eventType=r.eventType()==null?"UNKNOWN":r.eventType().name();String signature=header==null?r.signature():header;boolean verified=hmac(raw,props.getWebhookSecret()).equals(signature);if(!verified)throw new BusinessRuleException("Invalid webhook signature");if(r.gatewayPaymentId()!=null&&logs.existsByGatewayPaymentIdAndEventType(r.gatewayPaymentId(),eventType))return;var log=logs.save(PaymentWebhookLog.builder().eventType(eventType).gatewayOrderId(r.gatewayOrderId()).gatewayPaymentId(r.gatewayPaymentId()).signature(signature).rawPayload(raw).verified(true).receivedAt(Instant.now()).build());events.webhookReceived(new com.agacostays.payment.event.PaymentWebhookReceivedEvent("PaymentWebhookReceived",1,Instant.now(),r.eventType()==null?"UNKNOWN":r.eventType().name(),r.gatewayOrderId(),r.gatewayPaymentId(),verified));Payment p=payments.findFirstByGatewayOrderId(r.gatewayOrderId()).orElseThrow(()->new ResourceNotFoundException("Payment not found for webhook order"));if(r.eventType()==WebhookEventType.PAYMENT_CAPTURED||r.eventType()==WebhookEventType.PAYMENT_AUTHORIZED){p.setGatewayPaymentId(r.gatewayPaymentId());p.setPaymentStatus(PaymentStatus.SUCCESS);p.setPaidAt(Instant.now());p.setGatewaySignature(signature);payments.save(p);transactions.save(PaymentTransaction.builder().paymentId(p.getPaymentId()).transactionType("WEBHOOK_CAPTURE").amount(p.getAmount()).gatewayTransactionId(r.gatewayPaymentId()).status("SUCCESS").createdAt(Instant.now()).build());events.paymentSuccess(new com.agacostays.payment.event.PaymentSuccessEvent("PaymentSuccess",1,Instant.now(),p.getPaymentId(),p.getCustomerId(),p.getBranchId(),p.getReferenceId(),p.getAmount(),p.getPaymentFor().name(),p.getGatewayPaymentId(),UUID.randomUUID().toString()));} else if(r.eventType()==WebhookEventType.PAYMENT_FAILED){p.setPaymentStatus(PaymentStatus.FAILED);payments.save(p);events.paymentFailed(new com.agacostays.payment.event.PaymentFailedEvent("PaymentFailed",1,Instant.now(),p.getPaymentId(),p.getCustomerId(),p.getBranchId(),p.getReferenceId(),p.getAmount(),"Gateway webhook failure",UUID.randomUUID().toString()));}log.setProcessedAt(Instant.now());logs.save(log);} private String hmac(String raw,String secret){try{String s=(secret==null||secret.isBlank())?"local-development-secret":secret;Mac m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(s.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return java.util.HexFormat.of().formatHex(m.doFinal(raw.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}} }
